HTML='<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">\n<title>BL3 // Beyond Level 3</title>\n<style>\n:root{\n --bg:#03040b;--panel:rgba(7,9,26,.78);--panel2:rgba(12,15,38,.93);--line:rgba(131,102,255,.30);\n --violet:#9a4dff;--violet2:#5c36ff;--pink:#ff3ed1;--cyan:#5ee7ff;--blue:#5ba3ff;--gold:#ffc857;\n --red:#ff4d6d;--green:#49f5a8;--text:#f8f8ff;--muted:#a8afd0;--shadow:0 22px 70px rgba(0,0,0,.55);\n}\n*{box-sizing:border-box}html,body{margin:0;background:#02030a;color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;min-height:100%}body{overflow-x:hidden}\nbutton,input{font:inherit}.hidden{display:none!important}\n#app{min-height:100vh;position:relative;background:radial-gradient(circle at 50% -10%,rgba(96,34,180,.28),transparent 36%),#02030a}\n#app:before{content:"";position:fixed;inset:0;background:linear-gradient(180deg,rgba(1,2,8,.18),rgba(1,2,8,.84)),url("data:image/jpeg;base64,") center/cover no-repeat;opacity:.44;filter:saturate(1.1) contrast(1.08);z-index:0;pointer-events:none}\n.noise{position:fixed;inset:0;z-index:1;pointer-events:none;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox=\'0 0 180 180\' xmlns=\'http://www.w3.org/2000/svg\'%3E%3Cfilter id=\'n\'%3E%3CfeTurbulence type=\'fractalNoise\' baseFrequency=\'.88\' numOctaves=\'2\' stitchTiles=\'stitch\'/%3E%3C/filter%3E%3Crect width=\'100%25\' height=\'100%25\' filter=\'url(%23n)\' opacity=\'.18\'/%3E%3C/svg%3E")}\n.shell{position:relative;z-index:2;max-width:1680px;margin:auto;padding:18px}\n.topbar{height:78px;display:flex;align-items:center;gap:18px;padding:10px 16px;border:1px solid var(--line);background:rgba(4,6,20,.78);backdrop-filter:blur(20px);border-radius:22px;box-shadow:var(--shadow);position:sticky;top:10px;z-index:60}\n.brand{font-weight:1000;font-style:italic;font-size:38px;letter-spacing:-3px;text-shadow:0 0 24px rgba(163,74,255,.8);min-width:100px}.brand b{color:#fff}.brand span{font-size:10px;letter-spacing:3px;display:block;color:#d99fff;margin-top:-4px}\n.nav{display:flex;gap:7px;overflow:auto;flex:1}.nav button{white-space:nowrap;border:0;color:#cdd2f1;background:transparent;padding:12px 14px;border-radius:12px;font-weight:800;cursor:pointer}.nav button.active,.nav button:hover{background:linear-gradient(135deg,rgba(151,70,255,.24),rgba(64,212,255,.1));color:#fff;box-shadow:inset 0 0 0 1px rgba(164,111,255,.32)}\n.res{display:flex;gap:10px;align-items:center}.chip{border:1px solid var(--line);background:rgba(7,10,27,.82);padding:9px 12px;border-radius:12px;font-weight:850;white-space:nowrap}.chip small{color:var(--muted);font-weight:700}.avatar{width:48px;height:48px;border-radius:50%;background:radial-gradient(circle at 30% 20%,#d9b8ff,#5c36ff 55%,#140a2f);border:2px solid #9d68ff;box-shadow:0 0 24px rgba(148,74,255,.6)}\n.page{display:none;animation:fade .35s ease}.page.active{display:block}@keyframes fade{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n.hero{min-height:660px;margin-top:16px;border-radius:28px;overflow:hidden;position:relative;border:1px solid rgba(143,114,255,.3);box-shadow:var(--shadow);background:url("data:image/jpeg;base64,") center/cover no-repeat}\n.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(3,4,13,.72) 0%,rgba(3,4,13,.05) 45%,rgba(3,4,13,.7) 100%),linear-gradient(0deg,rgba(2,3,9,.86),transparent 45%)}\n.hero-content{position:absolute;z-index:2;left:50%;top:50%;transform:translate(-50%,-42%);text-align:center;width:min(900px,88%)}\n.kicker{font-size:12px;letter-spacing:4px;color:#d5b6ff;font-weight:900}.hero h1{font-size:clamp(54px,7vw,110px);line-height:.88;margin:16px 0 10px;letter-spacing:-5px;text-shadow:0 0 35px rgba(182,73,255,.7)}.hero h1 em{font-style:normal;color:#a96cff}.hero p{font-size:18px;color:#e0e4ff;max-width:700px;margin:0 auto 26px;text-shadow:0 2px 12px #000}\n.cta{border:1px solid #c987ff;color:#fff;background:linear-gradient(135deg,#7c34ff,#d23dff);box-shadow:0 0 35px rgba(168,62,255,.6),inset 0 0 18px rgba(255,255,255,.18);padding:18px 34px;border-radius:16px;font-size:22px;font-weight:1000;cursor:pointer;letter-spacing:.6px;transition:.2s}.cta:hover{transform:translateY(-3px) scale(1.02);filter:brightness(1.1)}\n.hero-bottom{position:absolute;z-index:3;left:18px;right:18px;bottom:18px;display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.mini{background:rgba(6,8,24,.8);border:1px solid rgba(131,102,255,.28);backdrop-filter:blur(12px);padding:13px 15px;border-radius:15px}.mini b{font-size:19px}.mini span{display:block;color:var(--muted);font-size:12px;margin-top:2px}\n.grid{display:grid;gap:16px}.grid4{grid-template-columns:repeat(4,1fr)}.grid3{grid-template-columns:repeat(3,1fr)}.grid2{grid-template-columns:repeat(2,1fr)}\n.section{margin-top:18px}.section-head{display:flex;align-items:end;justify-content:space-between;margin:0 4px 12px}.section-head h2{margin:0;font-size:26px}.section-head p{margin:3px 0 0;color:var(--muted)}\n.card{position:relative;border-radius:20px;overflow:hidden;border:1px solid var(--line);background:var(--panel);box-shadow:var(--shadow);min-height:170px}.card .bg{position:absolute;inset:0;background-position:center;background-size:cover;filter:saturate(1.15);opacity:.6}.card .shade{position:absolute;inset:0;background:linear-gradient(0deg,rgba(3,4,14,.94),rgba(3,4,14,.04))}.card .body{position:relative;z-index:2;padding:18px}.card h3{margin:0 0 4px;font-size:20px}.card p{margin:0;color:#c8cdea}.card.action{cursor:pointer;transition:.2s}.card.action:hover{transform:translateY(-4px);border-color:#a665ff;box-shadow:0 16px 52px rgba(103,40,180,.36)}\n.panel{background:linear-gradient(180deg,rgba(11,14,38,.94),rgba(5,7,22,.94));border:1px solid var(--line);border-radius:22px;box-shadow:var(--shadow);padding:20px}.panel h2,.panel h3{margin-top:0}.muted{color:var(--muted)}\n.progress{height:9px;background:#14172c;border-radius:99px;overflow:hidden;border:1px solid rgba(255,255,255,.06)}.progress>i{display:block;height:100%;background:linear-gradient(90deg,#6947ff,#ff3bd1);box-shadow:0 0 16px rgba(191,61,255,.8)}\n.btn{border:1px solid rgba(141,114,255,.32);background:#11152f;color:#fff;border-radius:12px;padding:11px 15px;font-weight:900;cursor:pointer}.btn.hot{background:linear-gradient(135deg,#7840ff,#d53cff);box-shadow:0 0 24px rgba(164,66,255,.34)}.btn.cyan{background:linear-gradient(135deg,#136bb2,#4bdfff)}.btn.red{background:linear-gradient(135deg,#90213a,#ff4d6d)}.btn:disabled{opacity:.45;cursor:not-allowed}\n/* arena */\n.arena-wrap{display:grid;grid-template-columns:280px 1fr 330px;gap:16px;margin-top:16px}.arena-stage{min-height:670px;border-radius:24px;position:relative;overflow:hidden;border:1px solid var(--line);background:url("data:image/jpeg;base64,") center/cover no-repeat;box-shadow:var(--shadow)}.arena-stage:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(2,3,11,.88),transparent 55%),radial-gradient(circle at 50% 50%,transparent 20%,rgba(2,3,10,.35) 100%)}\n.fighter{position:absolute;z-index:3;width:230px;height:280px;bottom:105px;border-radius:50%;filter:drop-shadow(0 0 28px rgba(146,78,255,.8));transition:.18s}.fighter.player{left:12%;background:radial-gradient(circle at 50% 45%,#b75cff 0 8%,#4f188e 25%,rgba(0,0,0,0) 60%)}.fighter.enemy{right:12%;background:radial-gradient(circle at 50% 45%,#ff5b6f 0 8%,#6e102a 25%,rgba(0,0,0,0) 60%)}\n.creature-core{position:absolute;inset:36px;border-radius:50% 45% 50% 40%;background:conic-gradient(from 210deg,#24104a,#9a45ff,#191d45,#ff3ed1,#271052);clip-path:polygon(50% 0,63% 20%,86% 12%,82% 37%,100% 52%,78% 61%,84% 90%,57% 79%,50% 100%,40% 78%,13% 91%,22% 61%,0 52%,18% 36%,14% 13%,38% 21%);box-shadow:inset 0 0 30px rgba(255,255,255,.22),0 0 35px rgba(160,61,255,.8)}.enemy .creature-core{background:conic-gradient(from 210deg,#2a0711,#ff4e6c,#34122a,#ff9b42,#2b0714);box-shadow:inset 0 0 30px rgba(255,255,255,.15),0 0 35px rgba(255,70,96,.8)}\n.eye{position:absolute;z-index:4;width:38px;height:16px;background:#fff;border-radius:60% 20%;top:115px;box-shadow:0 0 20px #fff}.player .eye{left:96px;transform:rotate(-10deg)}.enemy .eye{right:96px;transform:scaleX(-1) rotate(-10deg)}.eye:after{content:"";position:absolute;width:14px;height:14px;background:#151622;border-radius:50%;left:10px;top:1px}\n.hpbox{position:absolute;z-index:5;top:20px;width:40%;padding:13px;background:rgba(5,7,22,.8);border:1px solid var(--line);border-radius:16px;backdrop-filter:blur(10px)}.hpbox.left{left:20px}.hpbox.right{right:20px;text-align:right}.hpbar{height:14px;background:#1a1e38;border-radius:99px;overflow:hidden;margin-top:8px}.hpbar i{display:block;height:100%;background:linear-gradient(90deg,#43f6a9,#80ffda);transition:.35s}.right .hpbar i{margin-left:auto;background:linear-gradient(90deg,#ff9a4b,#ff496d)}\n.skillbar{position:absolute;z-index:6;left:50%;transform:translateX(-50%);bottom:20px;display:flex;gap:10px;background:rgba(4,6,18,.72);padding:10px;border:1px solid var(--line);border-radius:18px;backdrop-filter:blur(12px)}.skill{width:96px;height:82px;border-radius:14px;border:1px solid rgba(159,112,255,.35);background:linear-gradient(180deg,#191d44,#0d1028);color:#fff;font-weight:900;cursor:pointer;position:relative}.skill span{display:block;font-size:23px;margin-bottom:4px}.skill small{color:#c8ccef}.skill.cool{opacity:.45}.combo{position:absolute;z-index:8;left:50%;top:46%;transform:translate(-50%,-50%);font-size:58px;font-weight:1000;text-shadow:0 0 25px #b649ff;pointer-events:none;opacity:0}.combo.show{animation:pop .65s ease}@keyframes pop{0%{opacity:0;transform:translate(-50%,-40%) scale(.7)}35%{opacity:1;transform:translate(-50%,-52%) scale(1.1)}100%{opacity:0;transform:translate(-50%,-72%) scale(1)}}\n#fx{position:absolute;inset:0;z-index:7;pointer-events:none}.battle-log{max-height:430px;overflow:auto}.logline{padding:9px 10px;border-bottom:1px solid rgba(255,255,255,.06);font-size:13px;color:#d4d8ef}.logline b{color:#fff}\n/* creature lab */\n.creature-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.creature-card{min-height:330px;background:linear-gradient(180deg,rgba(18,20,51,.9),rgba(5,7,21,.96));border:1px solid var(--line);border-radius:20px;overflow:hidden;position:relative}.creature-art{height:190px;background:url("data:image/jpeg;base64,") center/cover no-repeat;position:relative}.creature-art:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,#080b20,transparent)}.creature-card .body{padding:16px}.rarity{display:inline-flex;padding:5px 8px;border-radius:8px;font-size:11px;font-weight:900;background:rgba(159,75,255,.2);color:#d6b6ff;border:1px solid rgba(159,75,255,.3)}\n.statrow{display:flex;gap:10px;margin-top:10px}.stat{flex:1;text-align:center;background:#0d1027;padding:8px;border-radius:10px}.stat b{display:block;font-size:18px}.stat small{color:var(--muted)}\n/* mission */\n.mission{display:grid;grid-template-columns:55px 1fr auto;gap:13px;align-items:center;padding:14px;border:1px solid rgba(124,112,255,.19);background:#0b0e27;border-radius:14px;margin-bottom:10px}.mission-icon{width:48px;height:48px;display:grid;place-items:center;border-radius:14px;background:linear-gradient(135deg,#623bff,#e43bff);font-size:23px}.reward{color:#ffd66d;font-weight:900}\n/* inventory */\n.inventory{display:grid;grid-template-columns:repeat(7,1fr);gap:10px}.item{aspect-ratio:1;border:1px solid rgba(133,105,255,.25);border-radius:14px;background:linear-gradient(135deg,#161a3a,#090c20);display:grid;place-items:center;position:relative;font-size:35px}.item small{position:absolute;bottom:6px;right:7px;font-size:10px;color:#d4d8f4}.item.legendary{box-shadow:inset 0 0 0 1px #f8b83c,0 0 22px rgba(255,188,59,.18)}\n/* leaderboard */\n.rankrow{display:grid;grid-template-columns:70px 1fr 160px 120px;gap:12px;align-items:center;padding:13px 15px;border-bottom:1px solid rgba(255,255,255,.07)}.rankno{font-size:22px;font-weight:1000;color:#cbaaff}.rankuser{display:flex;align-items:center;gap:10px}.ava{width:39px;height:39px;border-radius:50%;background:linear-gradient(135deg,#8e4cff,#44d5ff);box-shadow:0 0 15px rgba(111,80,255,.4)}\n/* modal */\n.modal{position:fixed;inset:0;z-index:200;background:rgba(1,2,8,.78);backdrop-filter:blur(12px);display:none;place-items:center;padding:20px}.modal.show{display:grid}.modalbox{width:min(620px,96vw);background:linear-gradient(180deg,#171a42,#07091d);border:1px solid #865dff;border-radius:24px;padding:25px;box-shadow:0 0 80px rgba(140,63,255,.4);text-align:center}.loot{font-size:64px;margin:10px}.modalbox h2{font-size:38px;margin:8px}\n.toast{position:fixed;z-index:250;right:22px;bottom:22px;background:#11162f;border:1px solid #7758ff;border-radius:14px;padding:13px 16px;box-shadow:var(--shadow);transform:translateY(30px);opacity:0;transition:.25s}.toast.show{transform:none;opacity:1}\n\n/* task hub */\n.task-hero{position:relative;overflow:hidden;border:1px solid rgba(157,92,255,.42);border-radius:24px;padding:28px;background:radial-gradient(circle at 82% 20%,rgba(113,54,255,.36),transparent 34%),linear-gradient(135deg,rgba(16,20,55,.98),rgba(6,8,24,.96));box-shadow:0 24px 70px rgba(0,0,0,.38)}\n.task-hero:after{content:"";position:absolute;right:-80px;top:-110px;width:320px;height:320px;border-radius:50%;border:1px solid rgba(112,87,255,.32);box-shadow:0 0 80px rgba(146,60,255,.2),inset 0 0 70px rgba(91,65,255,.15)}\n.task-hero h2{font-size:clamp(30px,4vw,55px);margin:5px 0}.task-hero p{max-width:760px;color:var(--muted);font-size:15px;line-height:1.7}.task-stats{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.task-stat{padding:10px 14px;border-radius:12px;background:rgba(10,13,36,.72);border:1px solid rgba(136,103,255,.25)}\n.task-filter{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.task-filter button{border:1px solid rgba(145,107,255,.27);background:#0a0d23;color:#cfd5ff;border-radius:999px;padding:9px 13px;cursor:pointer;font-weight:800}.task-filter button.active{background:linear-gradient(90deg,#713dff,#cf42ff);color:#fff;box-shadow:0 0 22px rgba(141,70,255,.28)}\n.task-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.task-card{position:relative;overflow:hidden;border:1px solid rgba(129,99,255,.28);border-radius:18px;background:linear-gradient(145deg,rgba(16,19,50,.96),rgba(6,8,24,.98));padding:17px;min-height:210px;transition:.22s}.task-card:hover{transform:translateY(-3px);border-color:rgba(185,118,255,.66);box-shadow:0 16px 40px rgba(0,0,0,.28),0 0 25px rgba(119,68,255,.14)}.task-card.done{opacity:.67;border-color:rgba(73,245,168,.4)}.task-brand{display:flex;align-items:center;gap:10px}.task-logo{width:42px;height:42px;border-radius:12px;background:linear-gradient(135deg,#7c42ff,#32d8ff);display:grid;place-items:center;font-weight:1000;box-shadow:0 0 18px rgba(120,64,255,.32)}.task-brand small{color:var(--muted)}.task-type{position:absolute;right:13px;top:13px;font-size:10px;font-weight:1000;letter-spacing:.12em;color:#cfc7ff;padding:6px 8px;border-radius:999px;background:rgba(111,68,255,.14);border:1px solid rgba(133,93,255,.22)}.task-card h3{margin:15px 0 6px;font-size:17px}.task-card p{color:var(--muted);line-height:1.5;font-size:13px;min-height:40px}.task-bottom{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:14px}.task-reward{font-weight:1000;color:#dba6ff}.task-btn{border:0;border-radius:11px;padding:10px 13px;background:linear-gradient(90deg,#663cff,#bb3dff);color:#fff;font-weight:1000;cursor:pointer}.task-btn.verify{background:linear-gradient(90deg,#145f7c,#22c8dd)}.task-btn.done{background:rgba(61,234,156,.13);color:#79f7b9;border:1px solid rgba(73,245,168,.25);cursor:default}.task-progress{height:5px;border-radius:10px;background:#171b3c;overflow:hidden;margin-top:10px}.task-progress i{display:block;height:100%;background:linear-gradient(90deg,#7c4cff,#f044ce)}.task-note{margin-top:16px;color:#7f89b4;font-size:11px}.taskpoints{border-color:rgba(217,111,255,.34)!important;color:#efc2ff}\n@media(max-width:1100px){.task-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.task-grid{grid-template-columns:1fr}.task-hero{padding:20px}}\n@media(max-width:1100px){.arena-wrap{grid-template-columns:1fr}.arena-wrap>.panel{order:2}.arena-stage{order:1}.grid4,.creature-grid{grid-template-columns:repeat(2,1fr)}.inventory{grid-template-columns:repeat(5,1fr)}.hero-bottom{grid-template-columns:repeat(2,1fr)}.res .chip:nth-child(2),.res .chip:nth-child(3){display:none}}\n@media(max-width:720px){.shell{padding:8px}.topbar{height:auto;flex-wrap:wrap}.brand{font-size:30px}.nav{order:3;width:100%}.res{margin-left:auto}.hero{min-height:620px}.hero h1{letter-spacing:-3px}.grid4,.grid3,.grid2,.creature-grid{grid-template-columns:1fr}.hero-bottom{grid-template-columns:1fr 1fr}.arena-stage{min-height:620px}.fighter{width:160px;height:210px;bottom:120px}.fighter.player{left:2%}.fighter.enemy{right:2%}.creature-core{inset:24px}.player .eye{left:65px;top:85px}.enemy .eye{right:65px;top:85px}.skillbar{gap:5px;width:96%;justify-content:center}.skill{width:23%;font-size:11px}.hpbox{width:46%}.inventory{grid-template-columns:repeat(4,1fr)}.rankrow{grid-template-columns:50px 1fr 80px}.rankrow>div:last-child{display:none}}\n</style>\n</head>\n<body>\n<div id="app"><div class="noise"></div><div class="shell">\n<header class="topbar">\n  <div class="brand"><b>BL3</b><span>BEYOND LEVEL 3</span></div>\n  <nav class="nav" id="nav">\n    <button class="active" data-page="home">HOME</button><button data-page="arena">ARENA</button><button data-page="creatures">CREATURES</button><button data-page="story">WORLDS</button><button data-page="missions">MISSIONS</button><button data-page="tasks">TASK HUB</button><button data-page="inventory">INVENTORY</button><button data-page="market">MARKET</button><button data-page="leaderboard">LEADERBOARD</button><button data-page="clan">CLAN</button>\n  </nav>\n  <div class="res"><div class="avatar"></div><div class="chip"><small>LV</small> <span id="levelTop">12</span></div><div class="chip">🪙 <span id="coinsTop">13,820</span></div><div class="chip">💎 <span id="gemsTop">2,450</span></div><div class="chip">⚡ <span id="energyTop">48</span>/50</div><div class="chip taskpoints">✦ <span id="taskPointsTop">0</span> SP</div></div>\n</header>\n\n<section class="page active" id="page-home">\n  <div class="hero">\n    <div class="hero-content"><div class="kicker">SEASON 01 // VOID RISING</div><h1>BUILD YOUR <em>LEGACY.</em></h1><p>Collect living Creatures. Enter cinematic Arenas. Evolve your power. Prove your rank across the BL3 universe.</p><button class="cta" onclick="openPage(\'arena\');startBattle()">▶ ENTER ARENA</button></div>\n    <div class="hero-bottom"><div class="mini"><b id="homeRank">#8841</b><span>GLOBAL RANK</span></div><div class="mini"><b id="homeWins">24</b><span>ARENA WINS</span></div><div class="mini"><b id="homeCreatures">6</b><span>CREATURES OWNED</span></div><div class="mini"><b id="homeStreak">3</b><span>WIN STREAK</span></div></div>\n  </div>\n  <div class="section"><div class="section-head"><div><h2>Jump Back In</h2><p>Your universe is alive.</p></div></div>\n  <div class="grid grid4">\n    <div class="card action" onclick="openPage(\'arena\')"><div class="bg" style="background-image:url(\'data:image/jpeg;base64,\')"></div><div class="shade"></div><div class="body"><h3>⚔ Arena</h3><p>Ranked combat & seasonal rewards.</p></div></div>\n    <div class="card action" onclick="openPage(\'creatures\')"><div class="bg" style="background-image:url(\'data:image/jpeg;base64,\')"></div><div class="shade"></div><div class="body"><h3>🐾 Creatures</h3><p>Grow, evolve and fuse new forms.</p></div></div>\n    <div class="card action" onclick="openPage(\'missions\')"><div class="bg" style="background-image:url(\'data:image/jpeg;base64,\')"></div><div class="shade"></div><div class="body"><h3>🎯 Missions</h3><p>Daily challenges and story quests.</p></div></div>\n    <div class="card action" onclick="openPage(\'clan\')"><div class="bg" style="background-image:url(\'data:image/jpeg;base64,\')"></div><div class="shade"></div><div class="body"><h3>👥 Clan</h3><p>Build a squad and climb together.</p></div></div>\n  </div></div>\n</section>\n\n<section class="page" id="page-arena">\n <div class="arena-wrap">\n  <aside class="panel"><div class="kicker">ARENA ZERO</div><h2>Ranked Battle</h2><p class="muted">Win battles to gain Crown Points and rise through divisions.</p><div style="margin:18px 0"><b>Division // VOID III</b><div class="progress" style="margin-top:8px"><i id="rankProg" style="width:62%"></i></div><small class="muted"><span id="cp">1,248</span> / 2,000 CP</small></div><h3>Enemy Intel</h3><div class="mini"><b id="enemyName">Crimson Beast</b><span>Lv. 13 // Fire Void</span></div><div class="mini"><b id="enemyPower">1,460</b><span>POWER</span></div><button class="btn hot" style="width:100%;margin-top:14px" onclick="newOpponent()">↻ Find Opponent</button></aside>\n  <main class="arena-stage" id="arenaStage"><canvas id="fx"></canvas><div class="hpbox left"><b>Shadowling // Lv. <span id="battleLevel">12</span></b><div class="hpbar"><i id="php" style="width:100%"></i></div><small><span id="pHpText">420</span> HP</small></div><div class="hpbox right"><b id="enemyTitle">Crimson Beast</b><div class="hpbar"><i id="ehp" style="width:100%"></i></div><small><span id="eHpText">460</span> HP</small></div><div class="fighter player" id="pf"><div class="creature-core"></div><div class="eye"></div></div><div class="fighter enemy" id="ef"><div class="creature-core"></div><div class="eye"></div></div><div class="combo" id="combo"></div><div class="skillbar"><button class="skill" onclick="skill(0)"><span>⚔</span>VOID CUT<small>18–34</small></button><button class="skill" id="s1" onclick="skill(1)"><span>💥</span>ALPHA BURST<small>CD 3</small></button><button class="skill" id="s2" onclick="skill(2)"><span>🛡</span>PHASE GUARD<small>BLOCK</small></button><button class="skill" id="s3" onclick="skill(3)"><span>⚡</span>CHAIN ARC<small>COMBO</small></button></div></main>\n  <aside class="panel"><div class="kicker">LIVE COMBAT</div><h3>Battle Feed</h3><div class="battle-log" id="battleLog"></div><div class="mini" style="margin-top:12px"><b>Reward</b><span>+180 Coins · +75 XP · Rank CP</span></div></aside>\n </div>\n</section>\n\n<section class="page" id="page-creatures"><div class="section-head"><div><div class="kicker">CREATURE LAB</div><h2>Your Living Collection</h2><p>Every Creature has traits, affinities and evolution paths.</p></div><button class="btn hot" onclick="hatchEgg()">🥚 HATCH EGG</button></div><div class="creature-grid" id="creatureGrid"></div><div class="section grid grid2"><div class="panel"><h2>Evolution Chamber</h2><p class="muted">Choose your active Creature and evolve it when its bond reaches the threshold.</p><div style="margin:18px 0"><b>Shadowling → Nightclaw</b><div class="progress" style="margin-top:8px"><i id="evoProg" style="width:68%"></i></div><small class="muted">1,240 / 2,000 Bond XP</small></div><button class="btn hot" onclick="evolve()">EVOLVE PREVIEW</button></div><div class="panel"><h2>Fusion Lab</h2><p class="muted">Fuse duplicate essence into rarer traits.</p><div class="mini"><b>Void Essence</b><span id="essence">340 / 500</span></div><button class="btn" style="margin-top:12px" onclick="toast(\'Need 160 more Void Essence\')">FUSE</button></div></div></section>\n\n<section class="page" id="page-story"><div class="section-head"><div><div class="kicker">WORLD MAP</div><h2>The BL3 Universe</h2><p>Campaign worlds unlock permanent perks and story relics.</p></div></div><div class="grid grid3" id="worldGrid"></div></section>\n\n<section class="page" id="page-missions"><div class="section-head"><div><div class="kicker">MISSION CONTROL</div><h2>Daily & Seasonal Missions</h2><p>Complete objectives to earn currencies, relics and Battle Pass XP.</p></div><div class="chip">⏱ RESET 08:21:44</div></div><div class="grid grid2"><div class="panel"><h2>Daily Missions <span class="muted" id="dailyDone">1/4</span></h2><div id="dailyMissions"></div></div><div class="panel"><h2>Season Journey</h2><div class="mini"><b>Void Rising // Tier <span id="tier">18</span></b><span>Season ends in 12D 8H</span></div><div class="progress" style="margin:14px 0"><i id="seasonProg" style="width:54%"></i></div><div class="grid grid3"><div class="item legendary">🧬<small>T19</small></div><div class="item legendary">💎<small>T20</small></div><div class="item legendary">👑<small>T21</small></div></div></div></div></section>\n\n<section class="page" id="page-tasks">\n  <div class="task-hero">\n    <div class="kicker">BL3 // SIGNAL QUEST NETWORK</div>\n    <h2>Complete real project quests. <em style="color:#d36cff">Earn Signal Points.</em></h2>\n    <p>Projects publish social, community and product missions. Hunters complete actions, submit proof and build a portable contribution score across the BL3 network.</p>\n    <div class="task-stats"><div class="task-stat"><b id="taskAvailable">8</b><br><small class="muted">LIVE QUESTS</small></div><div class="task-stat"><b id="taskEarned">0 SP</b><br><small class="muted">EARNED</small></div><div class="task-stat"><b id="taskDone">0</b><br><small class="muted">COMPLETED</small></div><div class="task-stat"><b>1.25x</b><br><small class="muted">HUNTER STREAK</small></div></div>\n  </div>\n  <div class="task-filter"><button class="active" onclick="setTaskFilter(\'all\',this)">ALL QUESTS</button><button onclick="setTaskFilter(\'social\',this)">SOCIAL</button><button onclick="setTaskFilter(\'community\',this)">COMMUNITY</button><button onclick="setTaskFilter(\'product\',this)">PRODUCT</button><button onclick="setTaskFilter(\'daily\',this)">DAILY FARM</button></div>\n  <div class="task-grid" id="taskGrid"></div>\n  <div class="task-note">Demo verification is local in this investor build. Production verification can be connected to project APIs, signed proofs, OAuth or manual moderation.</div>\n</section>\n\n<section class="page" id="page-inventory"><div class="section-head"><div><div class="kicker">VAULT</div><h2>Inventory</h2><p>Relics, gear, resources and cosmetics.</p></div><div class="chip"><span id="slots">31</span>/80 SLOTS</div></div><div class="panel"><div class="inventory" id="inventoryGrid"></div></div></section>\n\n<section class="page" id="page-market"><div class="section-head"><div><div class="kicker">NEXUS MARKET</div><h2>Featured Drops</h2><p>Cosmetics, eggs and upgrade materials.</p></div><div class="chip">ROTATES IN 04:12:09</div></div><div class="grid grid4" id="marketGrid"></div></section>\n\n<section class="page" id="page-leaderboard"><div class="section-head"><div><div class="kicker">CROWN RANKINGS</div><h2>Global Leaderboard</h2><p>Season 01 // Ranked Arena.</p></div></div><div class="panel" id="leaderboardRows"></div></section>\n\n<section class="page" id="page-clan"><div class="section-head"><div><div class="kicker">CLAN HQ</div><h2>VOIDWALKERS</h2><p>12 / 20 Hunters online · Clan Level 9</p></div><button class="btn hot" onclick="toast(\'Clan invite link copied\')">INVITE HUNTER</button></div><div class="grid grid3"><div class="panel"><h3>Clan War</h3><div class="mini"><b>VOIDWALKERS 2,840</b><span>vs NEON FANG 2,610</span></div><div class="progress" style="margin-top:15px"><i style="width:72%"></i></div><p class="muted">War ends in 18h 42m</p><button class="btn hot" onclick="openPage(\'arena\')">FIGHT FOR CLAN</button></div><div class="panel"><h3>Clan Research</h3><div class="mission"><div class="mission-icon">⚡</div><div><b>Energy Matrix II</b><div class="muted">+2 max energy for all members</div></div><div class="reward">82%</div></div><div class="mission"><div class="mission-icon">🪙</div><div><b>Gold Protocol I</b><div class="muted">+4% coin rewards</div></div><div class="reward">61%</div></div></div><div class="panel"><h3>Live Chat</h3><div class="battle-log"><div class="logline"><b>Kira:</b> season grind 🔥</div><div class="logline"><b>NeoHunter:</b> anyone for ranked?</div><div class="logline"><b>Arash:</b> pushed us to #72</div><div class="logline"><b>Luna:</b> Nightclaw evolved ✨</div></div><div style="display:flex;gap:8px;margin-top:10px"><input id="chatInput" placeholder="Message clan..." style="flex:1;background:#0b0e25;border:1px solid var(--line);color:#fff;padding:11px;border-radius:10px"><button class="btn" onclick="sendChat()">SEND</button></div></div></div></section>\n\n</div></div>\n\n<div class="modal" id="modal"><div class="modalbox"><div class="kicker" id="modalKicker">VICTORY</div><div class="loot" id="modalIcon">👑</div><h2 id="modalTitle">Arena Won</h2><p class="muted" id="modalText"></p><div style="display:flex;gap:10px;justify-content:center;margin-top:20px"><button class="btn hot" onclick="closeModal()">CONTINUE</button><button class="btn" onclick="closeModal();openPage(\'arena\');startBattle()">BATTLE AGAIN</button></div></div></div>\n<div class="toast" id="toast"></div>\n<script>\nconst DEFAULT={level:12,xp:1240,xpNeed:2000,coins:13820,gems:2450,energy:48,wins:24,streak:3,cp:1248,creatures:6,essence:340,tier:18,daily:[false,false,true,false],inventory:31,taskPoints:0,completedTasks:[],openedTasks:[]};\nlet state=Object.assign({},DEFAULT,JSON.parse(localStorage.getItem(\'bl3_final_state\')||\'{}\')); function save(){localStorage.setItem(\'bl3_final_state\',JSON.stringify(state));renderTop()}\nfunction renderTop(){levelTop.textContent=state.level;coinsTop.textContent=state.coins.toLocaleString();gemsTop.textContent=state.gems.toLocaleString();energyTop.textContent=state.energy;if(window.taskPointsTop)taskPointsTop.textContent=state.taskPoints||0;homeWins.textContent=state.wins;homeCreatures.textContent=state.creatures;homeStreak.textContent=state.streak;cp.textContent=state.cp;battleLevel.textContent=state.level;essence.textContent=state.essence+\' / 500\';tier.textContent=state.tier;slots.textContent=state.inventory}\nfunction openPage(name){document.querySelectorAll(\'.page\').forEach(p=>p.classList.remove(\'active\'));document.getElementById(\'page-\'+name).classList.add(\'active\');document.querySelectorAll(\'#nav button\').forEach(b=>b.classList.toggle(\'active\',b.dataset.page===name));window.scrollTo({top:0,behavior:\'smooth\'});if(name===\'arena\'&&!battle.active)startBattle()}\ndocument.querySelectorAll(\'#nav button\').forEach(b=>b.onclick=()=>openPage(b.dataset.page));\nfunction toast(t){let x=document.getElementById(\'toast\');x.textContent=t;x.classList.add(\'show\');setTimeout(()=>x.classList.remove(\'show\'),2200)}\nfunction showModal(k,i,t,txt){modalKicker.textContent=k;modalIcon.textContent=i;modalTitle.textContent=t;modalText.textContent=txt;modal.classList.add(\'show\')}function closeModal(){modal.classList.remove(\'show\')}\n// battle engine\nlet battle={active:false,p:420,e:460,maxp:420,maxe:460,guard:false,cool:[0,0,0,0],combo:0,turn:0};const enemies=[[\'Crimson Beast\',460,1460],[\'Void Reaper\',520,1580],[\'Neon Wyrm\',430,1510],[\'Astral Fang\',580,1690],[\'Rift Titan\',650,1820]];\nfunction logBattle(txt){let d=document.createElement(\'div\');d.className=\'logline\';d.innerHTML=txt;battleLog.prepend(d)}\nfunction setBars(){php.style.width=Math.max(0,battle.p/battle.maxp*100)+\'%\';ehp.style.width=Math.max(0,battle.e/battle.maxe*100)+\'%\';pHpText.textContent=Math.max(0,battle.p);eHpText.textContent=Math.max(0,battle.e)}\nfunction newOpponent(){let e=enemies[Math.floor(Math.random()*enemies.length)];enemyName.textContent=e[0];enemyTitle.textContent=e[0];enemyPower.textContent=e[2].toLocaleString();battle.maxe=e[1];startBattle()}\nfunction startBattle(){battle.active=true;battle.p=420+(state.level-12)*18;battle.maxp=battle.p;battle.e=battle.maxe||460;battle.guard=false;battle.cool=[0,0,0,0];battle.combo=0;battle.turn=0;battleLog.innerHTML=\'\';logBattle(\'<b>Battle started.</b> Your move, Hunter.\');setBars();updateSkills()}\nfunction updateSkills(){[0,1,2,3].forEach(i=>{let el=document.getElementById(\'s\'+i);if(el)el.classList.toggle(\'cool\',battle.cool[i]>0)})}\nfunction hitAnim(target,color,damage){let el=target===\'e\'?ef:pf;el.animate([{transform:\'translateX(0)\'},{transform:\'translateX(\'+(target===\'e\'?\'-22px\':\'22px\')+\') rotate(\'+(target===\'e\'?\'-4\':\'4\')+\'deg)\'},{transform:\'translateX(0)\'}],{duration:280});particles(target,color,damage)}\nfunction particles(target,color,damage){const c=fx,ctx=c.getContext(\'2d\');c.width=arenaStage.clientWidth;c.height=arenaStage.clientHeight;let cx=target===\'e\'?c.width*.78:c.width*.22,cy=c.height*.53;let ps=[];for(let i=0;i<28;i++)ps.push({x:cx,y:cy,vx:(Math.random()-.5)*8,vy:(Math.random()-.5)*8-2,a:1,r:2+Math.random()*5});let start=performance.now();function draw(now){ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle=color;ps.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.15;p.a-=.025;ctx.globalAlpha=Math.max(0,p.a);ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()});ctx.globalAlpha=1;ctx.font=\'900 32px system-ui\';ctx.fillStyle=\'#fff\';ctx.fillText(\'-\'+damage,cx-24,cy-55-(now-start)/12);if(now-start<650)requestAnimationFrame(draw);else ctx.clearRect(0,0,c.width,c.height)}requestAnimationFrame(draw)}\nfunction showCombo(t){combo.textContent=t;combo.classList.remove(\'show\');void combo.offsetWidth;combo.classList.add(\'show\')}\nfunction skill(i){if(!battle.active)return;if(battle.cool[i]>0){toast(\'Skill is cooling down\');return}let dmg=0;if(i===0){dmg=18+Math.floor(Math.random()*17);battle.combo++}if(i===1){dmg=48+Math.floor(Math.random()*25);battle.cool[1]=3;battle.combo=0;showCombo(\'ALPHA BURST!\')}if(i===2){battle.guard=true;battle.cool[2]=2;logBattle(\'🛡 <b>Phase Guard</b> activated.\');battle.turn++;enemyTurn();return}if(i===3){dmg=22+Math.floor(Math.random()*16)+(battle.combo*5);battle.cool[3]=2;showCombo(battle.combo>=2?\'CHAIN x\'+battle.combo:\'CHAIN ARC\');battle.combo++}if(Math.random()<.15){dmg=Math.floor(dmg*1.65);showCombo(\'CRITICAL!\')}battle.e-=dmg;hitAnim(\'e\',\'#c14bff\',dmg);logBattle(\'⚔ You dealt <b>\'+dmg+\'</b> damage.\');battle.turn++;setBars();if(battle.e<=0){winBattle();return}enemyTurn()}\nfunction enemyTurn(){setTimeout(()=>{if(!battle.active)return;let dmg=16+Math.floor(Math.random()*27);if(battle.guard){dmg=Math.floor(dmg*.25);battle.guard=false;showCombo(\'BLOCKED\')}battle.p-=dmg;hitAnim(\'p\',\'#ff4f70\',dmg);logBattle(\'🔥 \'+enemyTitle.textContent+\' dealt <b>\'+dmg+\'</b> damage.\');battle.cool=battle.cool.map(x=>Math.max(0,x-1));updateSkills();setBars();if(battle.p<=0)loseBattle()},520)}\nfunction winBattle(){battle.active=false;state.wins++;state.streak++;state.cp+=80+Math.floor(Math.random()*35);state.coins+=180;state.xp+=75;state.energy=Math.max(0,state.energy-2);let loot=Math.random()<.2?\'💎 Rare Void Shard\':\'🪙 180 Coins\';while(state.xp>=state.xpNeed){state.xp-=state.xpNeed;state.level++;state.xpNeed=Math.floor(state.xpNeed*1.18)}save();logBattle(\'👑 <b>VICTORY!</b> Rank points secured.\');showModal(\'VICTORY\',\'👑\',\'Arena Won\',\'+75 XP · +180 Coins · +Rank CP · Loot: \'+loot)}\nfunction loseBattle(){battle.active=false;state.streak=0;state.cp=Math.max(0,state.cp-35);state.energy=Math.max(0,state.energy-1);save();logBattle(\'☠ <b>Defeat.</b> Adapt and return.\');showModal(\'DEFEAT\',\'☠\',\'The Void Took This Round\',\'-35 CP · No loot lost. Your Creature is ready to fight again.\')}\n// creatures\nconst creatures=[[\'Shadowling\',\'DARK\',\'RARE\',12,85,72,68],[\'Frostbyte\',\'ICE\',\'EPIC\',11,78,84,73],[\'Embercub\',\'FIRE\',\'RARE\',10,91,60,75],[\'Aetherkin\',\'VOID\',\'LEGENDARY\',15,98,81,92],[\'Neon Fang\',\'ARC\',\'EPIC\',9,72,66,95],[\'Gravemite\',\'EARTH\',\'COMMON\',8,67,93,48]];\nfunction renderCreatures(){creatureGrid.innerHTML=creatures.map((c,i)=>`<div class="creature-card"><div class="creature-art" style="background-position:${i%2?\'65%\':\'35%\'} center"></div><div class="body"><span class="rarity">${c[2]}</span><h3>${c[0]} <span class="muted">Lv.${c[3]}</span></h3><p class="muted">${c[1]} affinity</p><div class="statrow"><div class="stat"><b>${c[4]}</b><small>ATK</small></div><div class="stat"><b>${c[5]}</b><small>DEF</small></div><div class="stat"><b>${c[6]}</b><small>SPD</small></div></div><button class="btn ${i===0?\'hot\':\'\'}" style="width:100%;margin-top:12px" onclick="toast(\'${i===0?\'Already active\':\'Creature selected: \'+c[0]}\')">${i===0?\'ACTIVE\':\'SELECT\'}</button></div></div>`).join(\'\')}\nfunction hatchEgg(){if(state.gems<200){toast(\'Need 200 Gems\');return}state.gems-=200;state.creatures++;save();showModal(\'HATCH COMPLETE\',\'🥚\',\'A Creature Awakened\',\'You discovered a new Creature essence. Collection size: \'+state.creatures)}function evolve(){showModal(\'EVOLUTION PREVIEW\',\'🧬\',\'Nightclaw Awaits\',\'Reach 2,000 Bond XP to evolve Shadowling into Nightclaw. New passive: Void Echo.\')}\n// worlds\nconst worlds=[[\'Nova Bastion\',\'01\',\'Unlocked\',\'Campaign 8/12\'],[\'Frost Helix\',\'02\',\'Unlocked\',\'Campaign 3/12\'],[\'Crimson Expanse\',\'03\',\'Locked\',\'Reach Lv. 15\'],[\'The Hollow Crown\',\'04\',\'Locked\',\'Complete World 03\'],[\'Aether Divide\',\'05\',\'Locked\',\'Season 02\'],[\'Origin Zero\',\'∞\',\'Unknown\',\'???\']];\nfunction renderWorlds(){worldGrid.innerHTML=worlds.map((w,i)=>`<div class="card action" onclick="${i<2?"toast(\'World selected: "+w[0]+"\')":"toast(\'World locked\')"}"><div class="bg" style="background-image:url(\'data:image/jpeg;base64,\');background-position:${20+i*12}% center"></div><div class="shade"></div><div class="body" style="min-height:230px;display:flex;flex-direction:column;justify-content:flex-end"><div class="kicker">WORLD ${w[1]}</div><h3>${w[0]}</h3><p>${w[2]} · ${w[3]}</p></div></div>`).join(\'\')}\n// missions\nconst missions=[[\'⚔\',\'Win 2 Arena Battles\',\'1 / 2\',\'🪙 100\'],[\'🧬\',\'Evolve a Creature\',\'0 / 1\',\'💎 50\'],[\'👥\',\'Play with a Clan Member\',\'1 / 1\',\'💎 50\'],[\'📦\',\'Open 1 Supply Cache\',\'0 / 1\',\'🪙 75\']];\nfunction renderMissions(){dailyMissions.innerHTML=missions.map((m,i)=>`<div class="mission"><div class="mission-icon">${m[0]}</div><div><b>${m[1]}</b><div class="muted">${m[2]}</div></div><div><div class="reward">${m[3]}</div><button class="btn" style="margin-top:5px" onclick="claimMission(${i})">${state.daily[i]?\'✓ DONE\':\'GO\'}</button></div></div>`).join(\'\');dailyDone.textContent=state.daily.filter(Boolean).length+\'/4\'}\nfunction claimMission(i){if(state.daily[i]){toast(\'Mission already completed\');return}if(i===0&&state.wins<25){openPage(\'arena\');return}state.daily[i]=true;state.coins+=75;save();renderMissions();toast(\'Mission reward claimed\')}\n// inventory & market\nconst items=[\'🗡️\',\'🛡️\',\'💎\',\'🧬\',\'🔥\',\'❄️\',\'⚡\',\'🪙\',\'🥚\',\'👑\',\'🧿\',\'🧪\',\'🔮\',\'🪶\',\'🗝️\',\'📜\',\'🌑\',\'🌟\',\'🦴\',\'💠\',\'🎟️\',\'🎭\',\'🧲\',\'🪬\',\'⚙️\',\'🧱\',\'🪨\',\'🧰\',\'🧿\',\'💣\',\'🧵\'];\nfunction renderInventory(){inventoryGrid.innerHTML=items.map((x,i)=>`<div class="item ${i%9===0?\'legendary\':\'\'}">${x}<small>x${1+(i*7)%14}</small></div>`).join(\'\')}\nconst market=[[\'Void Egg\',\'🥚\',200,\'gems\'],[\'Crown Cache\',\'👑\',650,\'coins\'],[\'Aether Relic\',\'🔮\',420,\'gems\'],[\'Energy Core\',\'⚡\',180,\'coins\'],[\'Nightclaw Skin\',\'🎭\',900,\'gems\'],[\'Fusion Essence\',\'🧬\',300,\'coins\'],[\'Arena Ticket\',\'🎟️\',120,\'coins\'],[\'Mythic Cache\',\'💠\',1200,\'gems\']];\nfunction renderMarket(){marketGrid.innerHTML=market.map((m,i)=>`<div class="panel" style="text-align:center"><div style="font-size:58px;margin:10px">${m[1]}</div><h3>${m[0]}</h3><p class="muted">Limited Nexus Drop</p><button class="btn hot" onclick="buy(${i})">${m[3]===\'gems\'?\'💎\':\'🪙\'} ${m[2]}</button></div>`).join(\'\')}\nfunction buy(i){let m=market[i];if(state[m[3]]<m[2]){toast(\'Not enough \'+m[3]);return}state[m[3]]-=m[2];state.inventory++;save();toast(m[0]+\' added to Inventory\')}\n// leaderboard\nconst names=[\'Vanta\',\'Kira\',\'NeoHunter\',\'Luna\',\'Arash\',\'Cypher\',\'Zed\',\'Nyx\',\'Riven\',\'Echo\',\'Hunter\'];\nfunction renderLeaderboard(){leaderboardRows.innerHTML=names.map((n,i)=>`<div class="rankrow"><div class="rankno">#${i+1}</div><div class="rankuser"><div class="ava"></div><div><b>${n}</b><div class="muted">Lv.${28-i}</div></div></div><div><b>${(4820-i*271).toLocaleString()} CP</b></div><div>${i<3?\'👑\':\'VOID \'+(i<6?\'I\':\'II\')}</div></div>`).join(\'\')}\nfunction sendChat(){let v=chatInput.value.trim();if(!v)return;toast(\'Message sent to Clan\');chatInput.value=\'\'}\n\n// Signal Quest Network\nconst PROJECT_TASKS=[\n{id:\'n1\',project:\'NOVA\',logo:\'N\',type:\'social\',label:\'SOCIAL\',title:\'Follow @NovaProtocol\',desc:\'Follow the project account and keep it followed through verification.\',reward:35},\n{id:\'n2\',project:\'NOVA\',logo:\'N\',type:\'social\',label:\'SOCIAL\',title:\'Like + Repost Launch Post\',desc:\'Amplify the featured launch post from the project campaign.\',reward:55},\n{id:\'r1\',project:\'RIFT\',logo:\'R\',type:\'community\',label:\'COMMUNITY\',title:\'Join Community\',desc:\'Join the campaign community and unlock the Rift Hunter role.\',reward:70},\n{id:\'r2\',project:\'RIFT\',logo:\'R\',type:\'product\',label:\'PRODUCT\',title:\'Try the Rift Testnet\',desc:\'Open the product, complete one core action and submit your proof.\',reward:120},\n{id:\'a1\',project:\'AETHER\',logo:\'A\',type:\'social\',label:\'SOCIAL\',title:\'Quote the Alpha Thread\',desc:\'Quote-post the campaign thread with your own useful takeaway.\',reward:80},\n{id:\'a2\',project:\'AETHER\',logo:\'A\',type:\'product\',label:\'PRODUCT\',title:\'Product Feedback\',desc:\'Complete the 2-minute product flow and leave one actionable note.\',reward:150},\n{id:\'b1\',project:\'BL3\',logo:\'3\',type:\'daily\',label:\'DAILY\',title:\'Daily Signal Check-in\',desc:\'Return to BL3 and keep your Hunter contribution streak alive.\',reward:25},\n{id:\'b2\',project:\'BL3\',logo:\'3\',type:\'daily\',label:\'DAILY\',title:\'Farm 3 Arena Wins\',desc:\'Win three Arena battles today to earn the daily network bonus.\',reward:90}\n];\nlet currentTaskFilter=\'all\';\nfunction taskIsDone(id){return (state.completedTasks||[]).includes(id)}\nfunction taskIsOpened(id){return (state.openedTasks||[]).includes(id)}\nfunction setTaskFilter(f,el){currentTaskFilter=f;document.querySelectorAll(\'.task-filter button\').forEach(b=>b.classList.remove(\'active\'));if(el)el.classList.add(\'active\');renderTaskHub()}\nfunction openProjectTask(id){if(taskIsDone(id))return;state.openedTasks=state.openedTasks||[];if(!state.openedTasks.includes(id))state.openedTasks.push(id);save();renderTaskHub();toast(\'Task opened — complete the action, then verify proof.\')}\nfunction verifyProjectTask(id){if(taskIsDone(id))return;let t=PROJECT_TASKS.find(x=>x.id===id);state.completedTasks=state.completedTasks||[];state.completedTasks.push(id);state.taskPoints=(state.taskPoints||0)+t.reward;state.coins+=Math.round(t.reward*2);save();renderTaskHub();showModal(\'SIGNAL VERIFIED\',\'✦\',\'+\'+t.reward+\' SIGNAL POINTS\',t.project+\' quest complete. Your contribution score just increased.\')}\nfunction renderTaskHub(){if(!window.taskGrid)return;let completed=state.completedTasks||[];let list=PROJECT_TASKS.filter(t=>currentTaskFilter===\'all\'||t.type===currentTaskFilter);taskGrid.innerHTML=list.map(t=>{let done=taskIsDone(t.id),opened=taskIsOpened(t.id);let btn=done?`<button class="task-btn done">✓ VERIFIED</button>`:opened?`<button class="task-btn verify" onclick="verifyProjectTask(\'${t.id}\')">VERIFY PROOF</button>`:`<button class="task-btn" onclick="openProjectTask(\'${t.id}\')">OPEN TASK</button>`;return `<div class="task-card ${done?\'done\':\'\'}"><span class="task-type">${t.label}</span><div class="task-brand"><div class="task-logo">${t.logo}</div><div><b>${t.project}</b><br><small>Verified Campaign</small></div></div><h3>${t.title}</h3><p>${t.desc}</p><div class="task-progress"><i style="width:${done?100:opened?55:10}%"></i></div><div class="task-bottom"><div class="task-reward">✦ ${t.reward} SP</div>${btn}</div></div>`}).join(\'\');taskEarned.textContent=(state.taskPoints||0)+\' SP\';taskDone.textContent=completed.length;taskAvailable.textContent=PROJECT_TASKS.length-completed.length;}\n\n// keyboard shortcut\nwindow.addEventListener(\'keydown\',e=>{if(document.getElementById(\'page-arena\').classList.contains(\'active\')){if(e.key===\'1\')skill(0);if(e.key===\'2\')skill(1);if(e.key===\'3\')skill(2);if(e.key===\'4\')skill(3)}})\nrenderTop();renderCreatures();renderWorlds();renderMissions();renderTaskHub();renderInventory();renderMarket();renderLeaderboard();\n</script>\n</body></html>'
@app.get("/")
def home(): return Response(HTML,mimetype="text/html")
@app.get("/health")
def health(): return jsonify(ok=True,build=BUILD)
@app.get("/version")
def version(): return jsonify(build=BUILD)
if __name__=="__main__":
    port=int(os.getenv("PORT","5000"))
    print(f"BL3 FINAL GAME running on http://127.0.0.1:{port}")
    app.run(host="0.0.0.0",port=port,debug=False)
